=head2 Google::Cloud::Bigquery::Analyticshub::V1::Analyticshub::Subscription

A subscription represents a subscribers' access to a particular set of
published data. It contains references to associated listings,
data exchanges, and linked datasets.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->listing() >> / C<< $msg->listing($value) >>

Type: C<String>

Output only. Resource name of the source Listing.
e.g. projects/123/locations/us/dataExchanges/456/listings/789

=item * C<< $msg->data_exchange() >> / C<< $msg->data_exchange($value) >>

Type: C<String>

Output only. Resource name of the source Data Exchange.
e.g. projects/123/locations/us/dataExchanges/456

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. The resource name of the subscription.
e.g. `projects/myproject/locations/us/subscriptions/123`.

=item * C<< $msg->creation_time() >> / C<< $msg->creation_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Timestamp when the subscription was created.

=item * C<< $msg->last_modify_time() >> / C<< $msg->last_modify_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Timestamp when the subscription was last modified.

=item * C<< $msg->organization_id() >> / C<< $msg->organization_id($value) >>

Type: C<String>

Output only. Organization of the project this subscription belongs to.

=item * C<< $msg->organization_display_name() >> / C<< $msg->organization_display_name($value) >>

Type: C<String>

Output only. Display name of the project of this subscription.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Bigquery::Analyticshub::V1::Subscription::State>)

Output only. Current state of the subscription.

=item * C<< $msg->linked_dataset_map() >> / C<< $msg->linked_dataset_map($value) >>

Type: C<Message> (L<Google::Cloud::Bigquery::Analyticshub::V1::Analyticshub::Subscription::LinkedDatasetMapEntry>)

Output only. Map of listing resource names to associated linked resource,
e.g. projects/123/locations/us/dataExchanges/456/listings/789
->
projects/123/datasets/my_dataset

For listing-level subscriptions, this is a map of size 1.
Only contains values if state == STATE_ACTIVE.

=item * C<< $msg->subscriber_contact() >> / C<< $msg->subscriber_contact($value) >>

Type: C<String>

Output only. Email of the subscriber.

=item * C<< $msg->linked_resources() >> / C<< $msg->linked_resources($value) >>

Type: C<Message> (L<Google::Cloud::Bigquery::Analyticshub::V1::Analyticshub::Subscription::LinkedResource>)

Output only. Linked resources created in the subscription. Only contains
values if state = STATE_ACTIVE.

=item * C<< $msg->resource_type() >> / C<< $msg->resource_type($value) >>

Type: C<Enum> (L<Google::Cloud::Bigquery::Analyticshub::V1::SharedResourceType>)

Output only. Listing shared asset type.

=item * C<< $msg->commercial_info() >> / C<< $msg->commercial_info($value) >>

Type: C<Message> (L<Google::Cloud::Bigquery::Analyticshub::V1::Analyticshub::Subscription::CommercialInfo>)

Output only. This is set if this is a commercial subscription i.e. if this
subscription was created from subscribing to a commercial listing.

=item * C<< $msg->log_linked_dataset_query_user_email() >> / C<< $msg->log_linked_dataset_query_user_email($value) >>

Type: C<Bool>

Output only. By default, false.
If true, the Subscriber agreed to the email sharing mandate
that is enabled for DataExchange/Listing.

=item * C<< $msg->destination_dataset() >> / C<< $msg->destination_dataset($value) >>

Type: C<Message> (L<Google::Cloud::Bigquery::Analyticshub::V1::Analyticshub::DestinationDataset>)

Optional. BigQuery destination dataset to create for the subscriber.

=back

=head3 Enum: Subscription::State

=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<STATE_ACTIVE> => C<1>

=item * C<STATE_STALE> => C<2>

=item * C<STATE_INACTIVE> => C<3>

=back

